"""Manual withdraw controls for the local console."""
LIVE_WITHDRAW_HTML = "<section style=\"border:1px solid #415469;padding:16px;margin-top:24px;border-radius:8px\">\n<h2>Live withdrawal — manual MetaMask authorization</h2>\n<p>Withdraw up to 10 USDC from the selected Gauntlet vault. No approval required. Each transaction requires separate authorization.</p>\n<label>USDC amount <input id=\"wdAmount\" type=\"text\" value=\"5\" style=\"padding:8px\"></label>\n<button id=\"wdQuote\">Obtain live quote</button>\n<button id=\"wdSubmit\" disabled>Review & authorize in MetaMask</button><button id=\"wdRecheck\" disabled>Recheck submitted transaction</button>\n<pre id=\"wdResult\">No active quote</pre>\n</section>\n<script>\nlet wdQuote = null; let wdLastSubmitted=null;\nconst wdStatus = (text) => document.getElementById('wdResult').textContent=text;\nasync function wdVerify(){\n if(!window.ethereum)throw Error('MetaMask unavailable');\n const accounts=await window.ethereum.request({method:'eth_accounts'});\n const chain=await window.ethereum.request({method:'eth_chainId'});\n if(accounts[0]?.toLowerCase()!==settings.wallet.toLowerCase()||chain!=='0x2105')\n   throw Error('Selected wallet or network differs from LVS configuration');\n}\nasync function wdPost(path,data){\n const response=await fetch(path,{method:'POST',credentials:'same-origin',\n headers:{'Content-Type':'application/json','X-LVS-Token':settings.token},body:JSON.stringify(data)});\n const result=await response.json();\n if(!response.ok)throw Error(result.error || 'Rejected by preflight');\n return result;\n}\ndocument.getElementById('wdQuote').onclick=async()=>{\n wdQuote=null;document.getElementById('wdSubmit').disabled=true;\n try{\n  await wdVerify();\n  const input=document.getElementById('wdAmount').value.trim();\n  if(!/^(?:0|[1-9]\\d*)(?:\\.\\d{1,6})?$/.test(input))throw Error('Invalid USDC amount');\n  const [whole,fract='']=input.split('.');\n  const units=BigInt(whole)*1000000n+BigInt(fract.padEnd(6,'0'));\n  if(units<1n||units>10000000n)throw Error('Amount must be greater than zero and at most 10 USDC');\n  wdQuote=await wdPost('/api/withdraw/quote',{amount_units:Number(units)});\n  wdStatus(JSON.stringify(wdQuote,null,2));\n  document.getElementById('wdSubmit').disabled=false;\n }catch(e){wdStatus('Quote rejected: '+e.message)}\n};\ndocument.getElementById('wdSubmit').onclick=async()=>{\n const original=wdQuote;wdQuote=null;\n document.getElementById('wdSubmit').disabled=true;\n if(!original)return;\n try{\n  await wdVerify();\n  const message='Authorize '+original.stage+' of '+(original.amount_units/1e6)+\n   ' USDC? Destination '+original.to+'. Review ALL data in MetaMask. No automatic next step.';\n  if(!window.confirm(message))return;\n  const ready=await wdPost('/api/withdraw/consume',{quote_id:original.quote_id});\n  await wdVerify();\n  const tx={from:ready.wallet,to:ready.to,data:ready.data,value:ready.value,gas:ready.gas};\n  const hash=await window.ethereum.request({method:'eth_sendTransaction',params:[tx]});\n  wdStatus('MetaMask submitted '+hash+'. Checking independent on-chain receipt...');\n  wdLastSubmitted={quote_id:original.quote_id,tx_hash:hash};\n  document.getElementById('wdRecheck').disabled=false;\n  const receipt=await wdPost('/api/withdraw/check',wdLastSubmitted);\n  wdStatus(JSON.stringify(receipt,null,2));\n }catch(e){wdStatus('Stopped: '+e.message+'. If MetaMask sent a transaction, check wallet activity before trying again.')}\n};\ndocument.getElementById('wdRecheck').onclick=async()=>{\n if(!wdLastSubmitted)return;\n try{await wdVerify();wdStatus(JSON.stringify(await wdPost('/api/withdraw/check',wdLastSubmitted),null,2));}\n catch(e){wdStatus('Receipt recheck failed: '+e.message)}\n};\n</script>"
